use crate::{engine::{Engine,SyncOptions},sftp::Profile};
use std::{path::PathBuf,time::{Duration,Instant},sync::Arc};
#[test]#[ignore="generated localhost four-way actual Engine comparison"]fn generated_listing_engine(){
 assert_eq!(std::env::var("NEARLY_REMOTE_SCAN_QA").as_deref(),Ok("GENERATED_ONLY"));
 let p=PathBuf::from(std::env::var("NEARLY_REMOTE_SCAN_FIXTURE").unwrap()).canonicalize().unwrap();let base=p.parent().unwrap();let allowed=PathBuf::from(env!("CARGO_MANIFEST_DIR")).parent().unwrap().parent().unwrap().join("sync-r41-concurrent-inventory/runs").canonicalize().unwrap();assert!(base.starts_with(&allowed));assert_eq!(std::fs::read(base.join("generated.marker")).unwrap(),b"GENERATED_ONLY");let v:serde_json::Value=serde_json::from_slice(&std::fs::read(&p).unwrap()).unwrap();assert_eq!(v["generatedOnly"],true);
 let key=PathBuf::from(v["key"].as_str().unwrap()).canonicalize().unwrap();let local=PathBuf::from(v["local"].as_str().unwrap()).canonicalize().unwrap();assert!(key.starts_with(base)&&local.starts_with(base));let port:u16=v["port"].as_u64().unwrap().try_into().unwrap();assert!(port>1024);
 let profile=Profile{id:"generated-engine".into(),name:"generated-only".into(),host:"127.0.0.1".into(),port,user:"fixture".into(),auth:"key".into(),mode:"sftp".into(),key_file:key.to_string_lossy().into_owned(),host_key:v["fingerprint"].as_str().unwrap().into()};
 let case=v["case"].as_str().unwrap_or("measure");let held=if case=="local-unreadable"{#[cfg(windows)]{use std::os::windows::fs::OpenOptionsExt;Some(std::fs::OpenOptions::new().read(true).share_mode(0).open(local.join("file.bin")).unwrap())}#[cfg(not(windows))]{panic!("Windows-only sharing fixture")}}else{None};
 let e=Arc::new(Engine::default());let id="generated-engine";let expected=v["expectedSent"].as_u64().unwrap_or(0);let run=crate::listing_probe::arm(expected);crate::listing_timing::start(run.start);let begin=run.start;
 e.start(id.into(),profile,local.to_string_lossy().into_owned(),"/sync/a/b".into(),zeroize::Zeroizing::new(v["passphrase"].as_str().unwrap().into()),SyncOptions{delete_removed:v["deleteRemoved"].as_bool().unwrap_or(true),..Default::default()}).unwrap();let start_return_us=begin.elapsed().as_micros();
 let report=if case=="cancel"{std::thread::sleep(Duration::from_millis(50));let before=serde_json::to_value(e.status(id).unwrap()).unwrap();assert_ne!(before["syncPhase"],"caught_up");e.stop(id).unwrap();assert!(e.status(id).is_err());serde_json::json!({"case":case,"cancelJoined":true,"before":before,"elapsedUs":begin.elapsed().as_micros()})}
 else if case!="measure"{let end=Instant::now()+Duration::from_secs(20);let status=loop{let s=e.status(id).unwrap();if s.failure.is_some(){break s}assert!(Instant::now()<end,"Expected failure not observed");std::thread::sleep(Duration::from_millis(10));};assert_eq!(status.sent,0);let value=serde_json::to_value(status).unwrap();e.stop(id).unwrap();serde_json::json!({"case":case,"expectedFailure":true,"status":value,"elapsedUs":begin.elapsed().as_micros()})}
 else{let event=run.wait(Duration::from_secs(120)).unwrap();let internal=event.caught_ns().expect("Incomplete actual Engine run");let s=e.status(id).unwrap();assert!(s.failure.is_none());assert_eq!(s.sent,expected);let value=serde_json::to_value(s).unwrap();assert_eq!(value["syncPhase"],"caught_up");e.stop(id).unwrap();serde_json::json!({"case":case,"internalCaughtUs":internal/1000,"startReturnUs":start_return_us,"stopReturnUs":begin.elapsed().as_micros(),"status":value,"optimized":!cfg!(debug_assertions),"scope":"Engine.start to worker caught_up; NOT GUI button-to-display"})};
 drop(held);let phases=crate::listing_timing::finish();let observer=run.finish();std::fs::write(base.join("engine-result.json"),serde_json::to_vec_pretty(&serde_json::json!({"report":report,"phases":phases,"observer":observer})).unwrap()).unwrap();
}
